package com.autodora.next.vision

import com.autodora.next.model.ShieldCategory
import com.autodora.next.model.WaveShieldChip

/**
 * Systematically audited 12x12 alpha-masked numeric feature descriptors for all major
 * actionable puzzle-solving Tower of Saviors battle status icons (across all 6 elements).
 * Each pixel encodes `(fgMask shl 24) or (r shl 16) or (g shl 8) or b`, excluding
 * transparent icon corners from battle-sky interference during real-time matching.
 */
data class OfficialIconTemplate(
    val iconId: String,
    val chipId: String,
    val defaultLabel: String,
    val paramInt: Int = 0,
    val paramElementMask: Int = 0,
    val fgCount: Int,
    val argb12x12: IntArray
) {
    fun toChips(): List<WaveShieldChip> {
        val cat = when (chipId) {
            "exact_first_combo", "min_combo", "min_first_combo", "equal_pair_light_dark", "same_combo_elements" -> ShieldCategory.COMBO
            "puzzle_shield", "cross_shield", "l_shape", "t_shape", "all_columns_ameliorate" -> ShieldCategory.SHAPE_AND_PUZZLE
            "zero_trail_burning" -> ShieldCategory.HAZARD_AND_PATH
            else -> ShieldCategory.COUNT_AND_ELEMENT
        }
        val out = ArrayList<WaveShieldChip>(2)
        out.add(WaveShieldChip(id = chipId, label = defaultLabel, category = cat, autoDetected = true, paramInt = paramInt, paramElementMask = paramElementMask))
        if ((chipId == "min_first_combo" || chipId == "same_combo_elements") && paramElementMask != 0) {
            out.add(WaveShieldChip(id = "require_elements", label = defaultLabel, category = ShieldCategory.COUNT_AND_ELEMENT, autoDetected = true, paramInt = 0, paramElementMask = paramElementMask))
        }
        return out
    }
}

object OfficialEnemyIconTemplates {
    const val GRID_SIZE = 12
    const val PIXEL_COUNT = 144

    val templates: List<OfficialIconTemplate> by lazy { RAW_SPECS }

    private fun hexToPacked12x12(hex: String): IntArray {
        val arr = IntArray(PIXEL_COUNT)
        var idx = 0
        var i = 0
        while (idx < PIXEL_COUNT && i + 8 <= hex.length) {
            arr[idx] = hex.substring(i, i + 8).toLong(16).toInt()
            idx++
            i += 8
        }
        return arr
    }

